def readable(value):
 if not isinstance(value,str): return value
 value=re.sub(r'(?<=[0-9])(?=[А-Яа-яЁё])|(?<=[А-Яа-яЁё])(?=[0-9])',' ',value)
 value=re.sub(r'(?<=[A-Za-z])(?=[А-Яа-яЁё])|(?<=[А-Яа-яЁё])(?=[A-Za-z])',' ',value)
 value=re.sub(r'\b(\d{3})\s([ЭНУЕЯВ])\b',r'\1\2',value)
 value=re.sub(r';(?=\S)','; ',value)
 return value
